from pathlib import Path
import json,html
p=Path(__file__).parent
scenes=json.loads((p/'scenes.json').read_text())
scenes[3]['action']='Milo sits beside his customer, with the wild-haired reference guiding his appearance. She calls the groomer.'
scenes[5]['action']='Cut to the same caller, speaking naturally. Milo stays off-screen rather than changing appearance.'
scenes[7]['action']='The same caller smiles as she accepts the offered appointment.'
scenes[10]['action']='Work finished, the groomer heads outside with her hiking bag.'
(p/'scenes.json').write_text(json.dumps(scenes,indent=2))
css='''@font-face{font-family:Apfel;src:url(../../../../public/fonts/apfel-grotezk/ApfelGrotezk-Regular.woff2)}@font-face{font-family:Runde;src:url(../../../../public/fonts/open-runde/OpenRunde-Regular.woff2)}*{box-sizing:border-box}body{margin:0;background:#fff;color:#1e3a34;font-family:Runde,Arial,sans-serif}.film{width:2560px;height:1440px;position:relative;overflow:hidden;background:#10291f}.photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.brand{position:absolute;top:70px;left:82px;color:white;font-size:24px;letter-spacing:2px;text-shadow:0 2px 10px #0009}.glass{position:absolute;right:100px;top:360px;width:700px;padding:42px;border-radius:44px;background:linear-gradient(140deg,#ffffffdb,#eff8f3ad);backdrop-filter:blur(28px) saturate(1.15);border:2px solid #ffffffc7;box-shadow:inset 0 1px 1px #fff,0 28px 70px #0c251c35;color:#1e3a34}.eyebrow{font-size:20px;letter-spacing:2px;text-transform:uppercase}.live{display:inline-block;width:12px;height:12px;border-radius:50%;background:#6caf93;margin-right:12px;box-shadow:0 0 0 8px #80bca526}.glass h2{font-family:Apfel;font-size:58px;line-height:1.08;font-weight:400;margin:22px 0}.glass p{font-size:25px;line-height:1.45;margin:14px 0}.mascot{width:140px;height:140px;object-fit:contain;mix-blend-mode:multiply;border-radius:30px}.topline{display:flex;align-items:center;gap:20px}.wave{display:flex;align-items:center;gap:9px;height:60px;margin-top:28px}.wave i{display:block;width:7px;border-radius:8px;background:#729e8d}.divider{height:1px;background:#1e3a3422;margin:28px 0}.time{background:#fff9;border:1px solid white;border-radius:24px;padding:24px 28px;margin-top:26px;display:flex;align-items:center;justify-content:space-between;font-size:28px}.time b{font-size:42px;font-weight:400}.check{width:58px;height:58px;background:#d3ece1;border-radius:50%;display:grid;place-items:center;font-size:36px}.spark{position:absolute;right:23px;top:3px;font-size:58px;transform:rotate(14deg);color:#8dbba6}.endshade{position:absolute;inset:0;background:linear-gradient(270deg,#09201799,transparent 65%)}.end{position:absolute;left:1750px;top:750px;width:720px;color:white}.end h2{text-shadow:0 2px 20px #0005}.end p{text-shadow:0 2px 15px #0008}.end h2{font-family:Apfel;font-weight:400;letter-spacing:-2px;font-size:76px;margin:0 0 25px}.end p{font-size:29px;margin:0 0 38px}.cta{display:inline-block;padding:25px 36px;background:#ffffffed;border:1px solid white;border-radius:50px;color:#1e3a34;font-size:27px}.pilot{position:absolute;bottom:40px;right:65px;color:#fff;font-size:16px;text-shadow:0 1px 5px #000}.mini{top:auto;bottom:105px;width:560px;padding:30px 38px}.mini h2{font-size:37px;margin:15px 0 0}.export .film{display:none}.export .film.active{display:block}'''
