(p/'compositions.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>AI Receptionist — finished scenes</title><style>'+css+'</style><body>'+''.join(films)+'</body></html>')
index='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A life beyond the next ring — scenes</title><style>*{box-sizing:border-box}body{margin:0;background:#fff;color:#1e3a34;font:16px system-ui}header{padding:25px 4vw;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dce6e0}h1{font-size:22px;margin:0}header small{display:block;color:#637e73;margin-top:5px}main{max-width:1500px;margin:auto;padding:26px 4vw}#hero{width:100%;aspect-ratio:16/9;object-fit:contain;background:#132b22}nav{display:flex;gap:10px;align-items:center;margin:20px 0}button,a{font:inherit;color:inherit}button{padding:10px 18px;border:1px solid #cddbd3;border-radius:30px;background:white;cursor:pointer}button:hover,button[aria-current=true]{background:#1e3a34;color:white}#count{margin:auto}#thumbs{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:25px 0}#thumbs button{padding:0;overflow:hidden;border-radius:10px;text-align:left}#thumbs img{width:100%;display:block}#thumbs span{display:block;padding:8px;font-size:12px}#notes{display:grid;grid-template-columns:1fr 1fr;gap:35px;line-height:1.6;border-top:1px solid #dce6e0;padding-top:20px}h2{font-size:25px;margin:0 0 8px}h3{font-size:12px;letter-spacing:1px;text-transform:uppercase}#audio{white-space:pre-line}a{font-size:13px}@media(max-width:700px){#thumbs{grid-template-columns:repeat(3,1fr)}#notes{grid-template-columns:1fr}header{align-items:start;gap:12px}}:focus-visible{outline:3px solid #5c9d83;outline-offset:3px}</style><header><div><h1>A life beyond the next ring.</h1><small>Approved character reference · corrected dogs · 12 scenes</small></div><a href="script.md">Full script ↗</a></header><main><img id="hero" alt=""><nav><button id="prev" aria-label="Previous scene">← Previous</button><span id="count" aria-live="polite"></span><button id="next" aria-label="Next scene">Next →</button><a id="download" download>Save image ↓</a></nav><div id="notes"><div><h2 id="title"></h2><p id="action"></p></div><div><h3>Dialogue / audio</h3><p id="audio"></p></div></div><div id="thumbs"></div></main><script>const scenes=SCENE_DATA;let active=0;const $=id=>document.getElementById(id);function show(i){active=(i+scenes.length)%scenes.length;const s=scenes[active];$('hero').src=s.image;$('hero').alt=s.title;$('title').textContent=s.title;$('count').textContent=String(s.number).padStart(2,'0')+' / 12 · '+s.time+' seconds';$('action').textContent=s.action;$('audio').textContent=s.audio;$('download').href=s.image;document.querySelectorAll('#thumbs button').forEach((b,j)=>b.setAttribute('aria-current',j===active));history.replaceState(null,'','#scene-'+s.number)}scenes.forEach((s,i)=>{const b=document.createElement('button');const img=document.createElement('img');img.src=s.image;img.alt=s.title;const span=document.createElement('span');span.textContent=String(s.number).padStart(2,'0')+' · '+s.title;b.append(img,span);b.onclick=()=>show(i);$('thumbs').append(b)});$('prev').onclick=()=>show(active-1);$('next').onclick=()=>show(active+1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(active+1);if(e.key==='ArrowLeft')show(active-1)});show(Math.max(0,Number(location.hash.replace('#scene-',''))-1));</script></html>'''
(p/'index.html').write_text(index.replace('SCENE_DATA',json.dumps(scenes)))
(p/'script.md').write_text('# A life beyond the next ring\n\n72-second film — final scene artwork pass. Happy Paws Grooming is a fictional demo business.\n\n'+'\n\n'.join(f'## {s["number"]:02}. {s["title"]} — {s["time"]}\n\n{s["action"]}\n\n{s["audio"]}' for s in scenes)+'\n\nIncoming AI booking requires a configured pilot. Returning-customer details established off-screen; interaction edited for time.\n')
